package com.parlour.management;
import static com.parlour.management.Db.*;
import java.util.*;
import java.time.*;
import java.sql.Timestamp;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Value;
@RestController
public class Bookings {
 final Db db;final Auth auth;final Catalog catalog;final Availability availability;final ObjectMapper json;final boolean paymentConfigured;
 Bookings(Db db,Auth auth,Catalog catalog,Availability availability,ObjectMapper json,@Value("${app.ssl-store-id}")String store,@Value("${app.ssl-store-password}")String pass){this.db=db;this.auth=auth;this.catalog=catalog;this.availability=availability;this.json=json;paymentConfigured=!store.isBlank()&&!pass.isBlank();}
 record Create(long parlour_id,List<Long> services,Long staff_id,Instant start_at,String customer_name,String customer_phone,String payment_method){}
 String encode(Object x){try{return json.writeValueAsString(x);}catch(Exception e){throw new IllegalStateException(e);}}
 @PostMapping("/api/bookings") Map<String,Object> create(@RequestBody Create b,@RequestHeader("Idempotency-Key")String key){long uid=id(auth.current(),"user_id");if(!"CUSTOMER".equals(auth.current().get("role")))throw error(403,"Use customer mode for booking");var me=db.one("SELECT * FROM users WHERE user_id=?",uid);if(me==null||((me.get("email")==null||me.get("email").toString().isBlank())&&me.get("password_hash")==null))throw error(403,"Please sign in or create an account to book a service.");validateCreate(b,key);long bid=db.tx(()->reserveTx(b,key,uid,false));return detail(bid);}
 void validateCreate(Create b,String key){if(key.isBlank()||key.length()>100||b.start_at()==null||b.customer_name()==null||b.customer_name().isBlank()||b.customer_name().length()>120||b.customer_phone()==null||!b.customer_phone().matches("\\+?[0-9 ()-]{7,25}"))throw error(400,"Invalid booking details");}
 long reserveTx(Create b,String key,long uid,boolean walkIn){String hash;try{hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(encode(b).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}
  catalog.lock(b.parlour_id());var prior=db.list("SELECT * FROM bookings WHERE customer_id=? AND idempotency_key=?",uid,key);if(!prior.isEmpty()){if(!hash.equals(prior.get(0).get("request_hash")))throw error(409,"Idempotency key was used for different details");return id(prior.get(0),"booking_id");}
  var parlour=catalog.verified(b.parlour_id());var selected=availability.selection(b.parlour_id(),b.services());var policy=db.one("SELECT * FROM cancellation_policies WHERE parlour_id=?",b.parlour_id());Long staff=availability.choose(b.parlour_id(),b.services(),b.staff_id(),b.start_at(),selected.minutes(),0);if(staff==null)throw error(409,"That slot is no longer available");
  boolean online="ONLINE".equals(b.payment_method());boolean split="SPLIT_50_50".equals(b.payment_method());boolean manual=Set.of("BKASH","NAGAD","BANK").contains(b.payment_method());if(!online&&!split&&!manual&&!"AT_PARLOUR".equals(b.payment_method()))throw error(400,"Choose a payment method");if(yes(policy.get("advance_required"))&&!online&&!split&&!manual)throw error(400,"This parlour requires advance payment");if((online||split)&&!paymentConfigured)throw error(503,"Online payments are not configured yet");BigDecimal advance=split?selected.total().divide(new BigDecimal(2),2,RoundingMode.HALF_UP):(online||manual)?selected.total().multiply(new BigDecimal(yes(policy.get("advance_required"))?policy.get("min_advance_pct").toString():"100")).divide(new BigDecimal(100),2,RoundingMode.HALF_UP):BigDecimal.ZERO;
  if((online||split)&&advance.signum()<=0)throw error(400,"Online payment requires a positive amount");String status=(online||split)?"PENDING_PAYMENT":yes(policy.get("owner_approval"))&&!walkIn?"PENDING_OWNER":"CONFIRMED";
  long ownerId=id(parlour,"owner_id");
  long bid=db.insert("bookings",map("customer_name",b.customer_name().trim(),"customer_phone",b.customer_phone(),"customer_id",uid,"parlour_id",b.parlour_id(),"staff_id",staff,"booking_date",java.sql.Date.valueOf(b.start_at().atZone(ZoneId.of(parlour.get("timezone").toString())).toLocalDate()),"start_at",Timestamp.from(b.start_at()),"end_at",Timestamp.from(b.start_at().plusSeconds(selected.minutes()*60L)),"total_amount",selected.total(),"advance_amount",advance,"payment_method",b.payment_method(),"status",status,"idempotency_key",key,"request_hash",hash,"hold_until",(online||split)?Timestamp.from(Instant.now().plusSeconds(900)):null,"policy_snapshot",encode(policy)));
  for(var s:selected.services())db.insert("booking_items",map("booking_id",bid,"service_id",id(s,"service_id"),"price",s.get("price"),"duration_min",s.get("duration_min")));notifyParties(bid,uid,ownerId,"BOOKING_CREATED","Appointment created",status);return bid;
 }
 Map<String,Object> accessible(long bid){var b=db.one("SELECT * FROM bookings WHERE booking_id=?",bid);var u=auth.current();long uid=id(u,"user_id");if("ADMIN".equals(u.get("role")))return b;if("OWNER".equals(u.get("role"))){auth.owner(id(b,"parlour_id"));return b;}if(uid!=id(b,"customer_id"))throw error(403,"Not your booking");return b;}
 Map<String,Object> detail(long bid){var b=accessible(bid);b.remove("request_hash");b.remove("idempotency_key");var items=db.list("SELECT * FROM booking_items WHERE booking_id=?",bid);for(var it:items)it.put("name",db.one("SELECT name FROM services WHERE service_id=?",id(it,"service_id")).get("name"));b.put("items",items);b.put("payments",db.list("SELECT payment_id,transaction_id,amount,method,gateway,status,paid_at FROM payments WHERE booking_id=?",bid));var paidAmt=paid(bid);b.put("paid_amount",paidAmt);b.put("due_amount",money(b.get("total_amount")).subtract(paidAmt));b.put("cash_on_service_amount",money(b.get("total_amount")).subtract(money(b.get("advance_amount"))));return b;}
 @GetMapping("/api/bookings/{bid}") Map<String,Object> get(@PathVariable long bid){return detail(bid);}
 @GetMapping("/api/bookings") List<Map<String,Object>> mine(){long uid=id(auth.current(),"user_id");var rows=db.list("SELECT * FROM bookings WHERE customer_id=? ORDER BY start_at DESC LIMIT 200",uid);var names=new HashMap<Long,String>();for(var r:rows){long pid=id(r,"parlour_id");r.put("parlour_name",names.computeIfAbsent(pid,k->db.one("SELECT name FROM parlours WHERE parlour_id=?",k).get("name").toString()));}return rows;}
 Map<String,Object> locked(long bid){var b=accessible(bid);catalog.lock(id(b,"parlour_id"));return accessible(bid);}
 @SuppressWarnings("unchecked") Map<String,Object> policy(Map<String,Object>b){try{return json.readValue(b.get("policy_snapshot").toString(),Map.class);}catch(Exception e){throw new IllegalStateException(e);}}
 static Instant instant(Object x){return x instanceof Timestamp t?t.toInstant():Instant.parse(x.toString());}
 void mutable(Map<String,Object>b){if(!Set.of("PENDING_PAYMENT","PENDING_OWNER","CONFIRMED").contains(b.get("status"))||!instant(b.get("start_at")).isAfter(Instant.now()))throw error(409,"This booking can no longer be changed");}
 /** Immutable notification parties, fetched BEFORE any write inside a transaction. */
 long[] parties(Map<String,Object> b){long pid=id(b,"parlour_id");return new long[]{id(b,"customer_id"),id(db.one("SELECT owner_id FROM parlours WHERE parlour_id=?",pid),"owner_id")};}
 void notifyParties(long bid,long customerId,long ownerId,String type,String title,String body){for(long uid:new long[]{customerId,ownerId})db.insert("notifications",map("user_id",uid,"booking_id",bid,"type",type,"title",title,"body",body));}
 @PostMapping("/api/bookings/{bid}/cancel") Map<String,Object> cancel(@PathVariable long bid){db.tx(()->{var b=locked(bid);if(Set.of("CANCELLED","CANCEL_PENDING").contains(b.get("status")))return;mutable(b);var p=policy(b);boolean timely=!Instant.now().isAfter(instant(b.get("start_at")).minusSeconds(((Number)p.get("cancel_window_hr")).longValue()*3600));BigDecimal paid=paid(bid);BigDecimal refund=paid.multiply(money(p.get("refund_pct"))).divide(new BigDecimal(100),2,RoundingMode.DOWN);if(!timely)refund=refund.subtract(money(b.get("total_amount")).multiply(money(p.get("fee_pct"))).divide(new BigDecimal(100),2,RoundingMode.UP)).max(BigDecimal.ZERO);var pt=parties(b);if(yes(p.get("manual_approval"))){db.update("UPDATE bookings SET cancel_refund_quote=?,status='CANCEL_PENDING' WHERE booking_id=?",refund,bid);notifyParties(bid,pt[0],pt[1],"CANCEL_PENDING","Cancellation requested","Owner approval is required");}else{cancelNow(bid,refund,pt);db.update("UPDATE bookings SET cancel_refund_quote=? WHERE booking_id=?",refund,bid);}});return detail(bid);}
 BigDecimal paid(long bid){BigDecimal sum=BigDecimal.ZERO;for(var r:db.list("SELECT amount FROM payments WHERE booking_id=? AND status='PAID'",bid))sum=sum.add(money(r.get("amount")));return sum;}
 void cancelNow(long bid,BigDecimal refund,long[] pt){queueRefund(bid,refund,"Booking cancelled");db.update("UPDATE bookings SET status='CANCELLED' WHERE booking_id=?",bid);notifyParties(bid,pt[0],pt[1],"CANCELLED","Appointment cancelled","Eligible refund: BDT "+refund);}
 void queueRefund(long bid,BigDecimal remaining,String reason){
  // All reads before any writes (Firestore tx rule).
  var payments=db.list("SELECT * FROM payments WHERE booking_id=? AND status='PAID' ORDER BY payment_id",bid);
  var toRefund=new java.util.ArrayList<java.util.Map<String,Object>>();
  for(var p:payments){BigDecimal amount=remaining.min(money(p.get("amount")));if(amount.signum()>0&&db.count("SELECT COUNT(*) FROM refund_requests WHERE payment_id=?",id(p,"payment_id"))==0){toRefund.add(map("payment_id",id(p,"payment_id"),"amount",amount));remaining=remaining.subtract(amount);}}
  for(var r:toRefund)db.insert("refund_requests",map("payment_id",r.get("payment_id"),"amount",r.get("amount"),"reason",reason));
 }
 record Move(Instant start_at,Long staff_id){}
 @PostMapping("/api/bookings/{bid}/reschedule") Map<String,Object> move(@PathVariable long bid,@RequestBody Move move){db.tx(()->{var b=locked(bid);mutable(b);var p=policy(b);if(!"CONFIRMED".equals(b.get("status"))||!"ALLOWED".equals(p.get("reschedule_rule"))||Instant.now().isAfter(instant(b.get("start_at")).minusSeconds(((Number)p.get("cancel_window_hr")).longValue()*3600)))throw error(409,"Rescheduling is outside the policy");var ids=db.list("SELECT service_id FROM booking_items WHERE booking_id=?",bid).stream().map(r->id(r,"service_id")).toList();int duration=(int)Duration.between(instant(b.get("start_at")),instant(b.get("end_at"))).toMinutes();long pid=id(b,"parlour_id");catalog.verified(pid);availability.selection(pid,ids);Long sid=availability.choose(pid,ids,move.staff_id(),move.start_at(),duration,bid);if(sid==null)throw error(409,"New slot unavailable");var zone=ZoneId.of(db.one("SELECT timezone FROM parlours WHERE parlour_id=?",pid).get("timezone").toString());var pt=parties(b);db.update("UPDATE bookings SET staff_id=?,start_at=?,end_at=?,booking_date=? WHERE booking_id=?",sid,Timestamp.from(move.start_at()),Timestamp.from(move.start_at().plusSeconds(duration*60L)),java.sql.Date.valueOf(move.start_at().atZone(zone).toLocalDate()),bid);notifyParties(bid,pt[0],pt[1],"RESCHEDULED","Appointment rescheduled",move.start_at().toString());});return detail(bid);}
 /** Owner reschedules a booking from the owner portal; both parties are notified. */
 @PostMapping("/api/owner/bookings/{bid}/reschedule") Map<String,Object> ownerMove(@PathVariable long bid,@RequestBody Move move){auth.require("OWNER");db.tx(()->{var b=locked(bid);if(!Set.of("PENDING_OWNER","CONFIRMED").contains(b.get("status"))||!instant(b.get("start_at")).isAfter(Instant.now()))throw error(409,"This booking can no longer be rescheduled");var ids=db.list("SELECT service_id FROM booking_items WHERE booking_id=?",bid).stream().map(r->id(r,"service_id")).toList();int duration=(int)Duration.between(instant(b.get("start_at")),instant(b.get("end_at"))).toMinutes();long pid=id(b,"parlour_id");catalog.verified(pid);availability.selection(pid,ids);Long sid=availability.choose(pid,ids,move.staff_id(),move.start_at(),duration,bid);if(sid==null)throw error(409,"New slot unavailable");var zone=ZoneId.of(db.one("SELECT timezone FROM parlours WHERE parlour_id=?",pid).get("timezone").toString());var pt=parties(b);db.update("UPDATE bookings SET staff_id=?,start_at=?,end_at=?,booking_date=? WHERE booking_id=?",sid,Timestamp.from(move.start_at()),Timestamp.from(move.start_at().plusSeconds(duration*60L)),java.sql.Date.valueOf(move.start_at().atZone(zone).toLocalDate()),bid);notifyParties(bid,pt[0],pt[1],"RESCHEDULED","Appointment rescheduled","The parlour moved your appointment to "+move.start_at().toString());});return detail(bid);}
 /** Owner books on behalf of a customer (phone or walk-in booking). The customer record is matched by phone or created new; owner-made bookings are confirmed immediately. */
 @PostMapping("/api/owner/bookings") Map<String,Object> ownerCreate(@RequestBody Create b){long owner=auth.require("OWNER");var p=db.one("SELECT * FROM parlours WHERE parlour_id=?",b.parlour_id());if(p==null||id(p,"owner_id")!=owner)throw error(403,"Not your parlour");String pm=b.payment_method()==null?"":b.payment_method();if(!Set.of("AT_PARLOUR","BKASH","NAGAD","BANK").contains(pm))throw error(400,"For a parlour booking choose pay at parlour, bKash, Nagad or bank");String key="owner-"+java.util.UUID.randomUUID();validateCreate(b,key);long cid;var existing=db.list("SELECT * FROM users WHERE phone=? AND role='CUSTOMER' ORDER BY user_id",b.customer_phone());if(!existing.isEmpty())cid=id(existing.get(0),"user_id");else cid=db.insert("users",map("name",b.customer_name().trim(),"phone",b.customer_phone(),"role","CUSTOMER","status","ACTIVE"));final long custId=cid;long bid=db.tx(()->reserveTx(b,key,custId,true));return detail(bid);}
 @GetMapping("/api/owner/bookings") List<Map<String,Object>> ownerBookings(){long owner=auth.require("OWNER");var out=new ArrayList<Map<String,Object>>();for(var p:db.list("SELECT parlour_id FROM parlours WHERE owner_id=?",owner))out.addAll(db.list("SELECT * FROM bookings WHERE parlour_id=? ORDER BY start_at DESC",id(p,"parlour_id")));out.sort((a,b)->instant(b.get("start_at")).compareTo(instant(a.get("start_at"))));for(var r:out){long bid=id(r,"booking_id");var pd=paid(bid);r.put("paid_amount",pd);r.put("due_amount",money(r.get("total_amount")).subtract(pd));}return out.size()>300?out.subList(0,300):out;}
 @PostMapping("/api/owner/bookings/{bid}/status") Map<String,Object> status(@PathVariable long bid,@RequestBody Map<String,Object>body){auth.require("OWNER");boolean[] removed={false};db.tx(()->{var b=locked(bid);String next=text(body,"status",24),old=b.get("status").toString();if(next.equals(old))return;var pt=parties(b);
  String reason=body.get("reason")==null?"":text(body,"reason",300);
  if(old.equals("PENDING_OWNER")&&next.equals("CONFIRMED")&&instant(b.get("start_at")).isAfter(Instant.now()))db.update("UPDATE bookings SET status=? WHERE booking_id=?",next,bid);
  else if((old.equals("PENDING_OWNER")||old.equals("CONFIRMED"))&&next.equals("REJECTED")){var refundDue=paid(bid);queueRefund(bid,refundDue,"Owner rejected appointment");db.update("UPDATE bookings SET status=?,status_reason=? WHERE booking_id=?",next,reason,bid);}
  else if(old.equals("CONFIRMED")&&next.equals("COMPLETED")&&!instant(b.get("end_at")).isAfter(Instant.now())){var arch=archiveRow(bid,b);db.update("DELETE FROM booking_items WHERE booking_id=?",bid);db.insert("completed_services",arch);db.update("DELETE FROM bookings WHERE booking_id=?",bid);removed[0]=true;}
  else if(old.equals("CANCEL_PENDING")&&next.equals("CANCELLED"))cancelNow(bid,money(b.get("cancel_refund_quote")),pt);
  else throw error(409,"Invalid booking transition");notifyParties(bid,pt[0],pt[1],next,"REJECTED".equals(next)?"Booking rejected":"Booking updated","REJECTED".equals(next)&&!reason.isBlank()?"Rejected by the parlour. Reason: "+reason:next);});return removed[0]?map("booking_id",bid,"status","COMPLETED","removed",true):detail(bid);
 }
 @PostMapping("/api/ratings") Map<String,Object> rate(@RequestBody Map<String,Object>b){return db.tx(()->{long bid=Long.parseLong(b.get("booking_id").toString());var booking=db.one("SELECT * FROM completed_services WHERE booking_id=?",bid);if(id(booking,"customer_id")!=id(auth.current(),"user_id"))throw error(403,"Only this completed booking's customer can review");String target=text(b,"target_type",16);if(!Set.of("PARLOUR","STAFF").contains(target))throw error(400,"Invalid review target");if(db.count("SELECT COUNT(*) FROM ratings WHERE booking_id=? AND target_type=?",bid,target)>0)throw error(409,"This visit was already reviewed");int score=Integer.parseInt(b.get("score").toString());if(score<1||score>5)throw error(400,"Score must be 1–5");long pid=id(booking,"parlour_id");Long sid=target.equals("STAFF")?id(booking,"staff_id"):null;var prior=sid==null?db.list("SELECT score FROM ratings WHERE parlour_id=? AND target_type='PARLOUR'",pid):db.list("SELECT score FROM ratings WHERE staff_id=? AND target_type='STAFF'",sid);double avg=(prior.stream().mapToLong(r->((Number)r.get("score")).longValue()).sum()+score)/(prior.size()+1.0);long rid=db.insert("ratings",map("booking_id",bid,"parlour_id",pid,"staff_id",sid,"target_type",target,"score",score,"review",text(b,"review",2000)));if(sid==null)db.update("UPDATE parlours SET rating=? WHERE parlour_id=?",avg,pid);else db.update("UPDATE staff SET rating=? WHERE staff_id=?",avg,sid);return map("rating_id",rid);});}
 /** Full archive snapshot of a booking, captured BEFORE any write inside the completion transaction. */
 Map<String,Object> archiveRow(long bid,Map<String,Object> b){
  var items=db.list("SELECT * FROM booking_items WHERE booking_id=?",bid);
  var sb=new StringBuilder();
  for(var it:items){var sv=db.one("SELECT name FROM services WHERE service_id=?",id(it,"service_id"));String nm=sv==null||sv.get("name")==null?"Service":String.valueOf(sv.get("name"));if(sb.length()>0)sb.append(", ");sb.append(nm);}
  var p=db.one("SELECT name FROM parlours WHERE parlour_id=?",id(b,"parlour_id"));
  Object staffName=null;if(b.get("staff_id")!=null){var st=db.one("SELECT name FROM staff WHERE staff_id=?",id(b,"staff_id"));if(st!=null)staffName=st.get("name");}
  return map("booking_id",bid,"customer_id",id(b,"customer_id"),"parlour_id",id(b,"parlour_id"),"staff_id",b.get("staff_id"),"completed_at",Timestamp.from(Instant.now()),"customer_name",b.get("customer_name"),"customer_phone",b.get("customer_phone"),"parlour_name",p==null?null:p.get("name"),"staff_name",staffName,"services_text",sb.toString(),"total_amount",b.get("total_amount"),"payment_method",b.get("payment_method"),"start_at",b.get("start_at"),"end_at",b.get("end_at"));
 }
 @GetMapping("/api/bookings/archive") List<Map<String,Object>> myArchive(){long uid=auth.require("CUSTOMER");var rows=db.list("SELECT * FROM completed_services WHERE customer_id=?",uid);rows.sort((x,y)->String.valueOf(y.get("completed_at")).compareTo(String.valueOf(x.get("completed_at"))));return rows;}
 @GetMapping("/api/owner/archive") List<Map<String,Object>> ownerArchive(){long uid=auth.require("OWNER");var mine=db.list("SELECT parlour_id FROM parlours WHERE owner_id=?",uid);var out=new ArrayList<Map<String,Object>>();for(var p:mine)out.addAll(db.list("SELECT * FROM completed_services WHERE parlour_id=?",id(p,"parlour_id")));out.sort((x,y)->String.valueOf(y.get("completed_at")).compareTo(String.valueOf(x.get("completed_at"))));return out;}
 /** Owner sends an offer/notification to every customer who has a completed visit at one of their parlours. */
 @PostMapping("/api/owner/customers/{cid}/rate") Map<String,Object> rateCustomer(@PathVariable long cid,@RequestBody Map<String,Object> b){long owner=auth.require("OWNER");return db.tx(()->{long bid=Long.parseLong(b.get("booking_id").toString());var arch=db.one("SELECT * FROM completed_services WHERE booking_id=?",bid);if(arch==null||id(arch,"customer_id")!=cid)throw error(400,"That completed visit is not this customer's");long pid=id(arch,"parlour_id");var p=db.one("SELECT * FROM parlours WHERE parlour_id=?",pid);if(p==null||id(p,"owner_id")!=owner)throw error(403,"Not your parlour");if(db.count("SELECT COUNT(*) FROM ratings WHERE booking_id=? AND target_type='CUSTOMER'",bid)>0)throw error(409,"This customer was already reviewed for this visit");int score=Integer.parseInt(b.get("score").toString());if(score<1||score>5)throw error(400,"Score must be 1-5");long rid=db.insert("ratings",map("booking_id",bid,"parlour_id",pid,"staff_id",null,"target_type","CUSTOMER","customer_id",cid,"score",score,"review",text(b,"review",2000)));return map("rating_id",rid);});}
 @GetMapping("/api/owner/customers/{cid}") Map<String,Object> customerProfile(@PathVariable long cid){auth.require("OWNER");var u=db.one("SELECT * FROM users WHERE user_id=?",cid);if(u==null||!"CUSTOMER".equals(u.get("role")))throw error(404,"Customer not found");var names=new HashMap<Long,String>();java.util.function.Function<Long,String> pname=k->names.computeIfAbsent(k,x->{var r=db.one("SELECT name FROM parlours WHERE parlour_id=?",x);return r==null?"":String.valueOf(r.get("name"));});var history=new ArrayList<Map<String,Object>>();for(var r:db.list("SELECT * FROM bookings WHERE customer_id=? ORDER BY start_at DESC LIMIT 100",cid)){var c=new HashMap<>(r);c.put("parlour_name",pname.apply(id(r,"parlour_id")));c.put("kind","BOOKING");history.add(c);}for(var r:db.list("SELECT * FROM completed_services WHERE customer_id=?",cid)){var c=new HashMap<>(r);c.put("parlour_name",pname.apply(id(r,"parlour_id")));c.put("kind","COMPLETED");history.add(c);}history.sort((a,b2)->String.valueOf(b2.getOrDefault("start_at",b2.getOrDefault("completed_at",""))).compareTo(String.valueOf(a.getOrDefault("start_at",a.getOrDefault("completed_at","")))));var reviews=new ArrayList<Map<String,Object>>();double sum=0;for(var r:db.list("SELECT * FROM ratings WHERE customer_id=? AND target_type='CUSTOMER'",cid)){var c=new HashMap<>(r);c.put("parlour_name",pname.apply(id(r,"parlour_id")));reviews.add(c);sum+=((Number)r.get("score")).doubleValue();}reviews.sort((a,b2)->String.valueOf(b2.get("created_at")).compareTo(String.valueOf(a.get("created_at"))));long completed=db.count("SELECT COUNT(*) FROM completed_services WHERE customer_id=?",cid);long cancelled=db.list("SELECT status FROM bookings WHERE customer_id=?",cid).stream().filter(r->"CANCELLED".equals(r.get("status"))||"REJECTED".equals(r.get("status"))).count();var cust=new HashMap<String,Object>();cust.put("user_id",cid);cust.put("name",u.get("name"));cust.put("phone",u.get("phone"));cust.put("email",u.get("email"));var out=new HashMap<String,Object>();out.put("customer",cust);out.put("avg_rating",reviews.isEmpty()?0:sum/reviews.size());out.put("reviews_count",reviews.size());out.put("completed_count",completed);out.put("cancelled_count",cancelled);out.put("history",history);out.put("reviews",reviews);return out;}
 @PostMapping("/api/owner/offers") Map<String,Object> sendOffer(@RequestBody Map<String,Object> b){long uid=auth.require("OWNER");long pid=Long.parseLong(String.valueOf(b.get("parlour_id")));var p=db.one("SELECT * FROM parlours WHERE parlour_id=?",pid);if(p==null||id(p,"owner_id")!=uid)throw error(403,"Not your parlour");String title=text(b,"title",120),body=text(b,"body",1000);var rows=db.list("SELECT customer_id FROM completed_services WHERE parlour_id=?",pid);var seen=new java.util.HashSet<Long>();int sent=0;for(var r:rows){long cid=id(r,"customer_id");if(!seen.add(cid))continue;db.insert("notifications",map("user_id",cid,"booking_id",0,"type","OFFER","title",title,"body",body));sent++;}return map("sent",sent);}
 double platformFeePct(){var rows=db.list("SELECT * FROM platform_settings");if(rows.isEmpty())return 5.0;Object v=rows.get(0).get("platform_fee_pct");return v==null?5.0:((Number)v).doubleValue();}
 /** Customer reports a manual payment (bKash/Nagad/bank transfer) with its transaction id. The platform charge is split out automatically; the owner confirms receipt. */
 @PostMapping("/api/bookings/{bid}/report-payment") Map<String,Object> reportPayment(@PathVariable long bid,@RequestBody Map<String,Object> b){long uid=auth.require("CUSTOMER");var bk=db.one("SELECT * FROM bookings WHERE booking_id=?",bid);if(bk==null)throw error(404,"Booking not found");if(id(bk,"customer_id")!=uid)throw error(403,"Not your booking");String method=text(b,"method",16);if(!Set.of("BKASH","NAGAD","BANK").contains(method))throw error(400,"Choose bKash, Nagad or Bank");String trx=text(b,"transaction_id",64);if(trx.isBlank())throw error(400,"Transaction ID is required");BigDecimal amount=new BigDecimal(String.valueOf(b.get("amount")));if(amount.signum()<=0)throw error(400,"Invalid amount");BigDecimal fee=amount.multiply(BigDecimal.valueOf(platformFeePct())).divide(BigDecimal.valueOf(100),2,RoundingMode.HALF_UP);long payId=db.insert("payments",map("booking_id",bid,"amount",amount,"method",method,"gateway","MANUAL","transaction_id",trx,"status","REPORTED","platform_charge",fee,"owner_amount",amount.subtract(fee),"created_at",Timestamp.from(Instant.now()),"paid_at",Timestamp.from(Instant.now())));return map("payment_id",payId,"platform_charge",fee,"owner_amount",amount.subtract(fee));}
 /** Owner confirms a reported manual payment was received; only then does it count as paid. */
 @PostMapping("/api/owner/payments/{payId}/confirm") Map<String,Object> confirmPayment(@PathVariable long payId){long uid=auth.require("OWNER");var pay=db.one("SELECT * FROM payments WHERE payment_id=?",payId);if(pay==null)throw error(404,"Payment not found");var bk=db.one("SELECT * FROM bookings WHERE booking_id=?",id(pay,"booking_id"));if(bk==null)throw error(404,"Booking not found");var p=db.one("SELECT * FROM parlours WHERE parlour_id=?",id(bk,"parlour_id"));if(p==null||id(p,"owner_id")!=uid)throw error(403,"Not your parlour");db.update("UPDATE payments SET status='PAID' WHERE payment_id=?",payId);return map("ok",true);}
}
